exercises.solution:
def pedir_entero(mensaje, minimo, maximo, intentos=3):
    """Pide un entero en [minimo, maximo]; lanza ValueError si se agotan los intentos."""
    for _ in range(intentos):
        texto = input(mensaje)
        try:
            numero = int(texto)
        except ValueError:
            print(f"{texto!r} no es un número entero.")
            continue
        if minimo <= numero <= maximo:
            return numero
        print(f"Debe estar entre {minimo} y {maximo}.")
    raise ValueError(f"sin respuesta válida tras {intentos} intentos")

tests.code:
try:
    capturar(pedir_entero, "Nota: ", 0, 10, intentos=2, entradas=["x", "11"])
except ValueError as e:
    assert "2" in str(e), f"El mensaje debe incluir el número de intentos (2); fue: {str(e)!r}"
except EOFError:
    raise AssertionError("Pediste más datos de la cuenta: con intentos=2 solo debes llamar a input() 2 veces")
else:
    raise AssertionError("Tras 2 intentos fallidos debe lanzarse ValueError")

try:
    capturar(pedir_entero, "N: ", 1, 5, entradas=["a", "9", "0"])
except ValueError as e:
    assert "3" in str(e), f"El mensaje debe incluir el número de intentos (3); fue: {str(e)!r}"
except EOFError:
    raise AssertionError("Pediste más datos de la cuenta: con intentos=3 solo debes llamar a input() 3 veces")
else:
