class ErrorBancario(Exception):
    """Base de todos los errores del banco."""


class ImporteInvalidoError(ErrorBancario):
    """El importe no es un número positivo."""


class SaldoInsuficienteError(ErrorBancario):
    """El saldo no cubre el importe solicitado."""

    def __init__(self, saldo, importe):
        super().__init__(f"Saldo insuficiente: saldo {saldo}, importe {importe}")
        self.saldo = saldo
        self.importe = importe
        self.faltante = importe - saldo


def retirar(saldo, importe):
    """Devuelve el saldo tras retirar importe; lanza ErrorBancario si no es posible."""
    if isinstance(importe, bool) or not isinstance(importe, (int, float)) or importe <= 0:
        raise ImporteInvalidoError(f"Importe no válido: {importe!r}")
    if importe > saldo:
        raise SaldoInsuficienteError(saldo, importe)
    return saldo - importe

