exercises.solution:
class ConfigError(Exception):
    """Error en la configuración de la aplicación."""


def obtener_puerto(config):
    """Devuelve el puerto como int; lanza ConfigError si falta o no es válido."""
    try:
        valor = config["puerto"]
    except KeyError as e:
        raise ConfigError("falta la clave 'puerto'") from e
    try:
        puerto = int(valor)
    except (ValueError, TypeError) as e:
        raise ConfigError(f"puerto no numérico: {valor!r}") from e
    if not 1 <= puerto <= 65535:
        raise ConfigError(f"puerto fuera de rango: {puerto}")
    return puerto

tests.code:
