def reintentar(funcion, intentos=3, excepciones=(Exception,)):
    """Llama a funcion() hasta intentos veces, reintentando ante excepciones."""
    if intentos < 1:
        raise ValueError(f"intentos debe ser al menos 1, recibido {intentos}")
    for numero in range(1, intentos + 1):
        try:
            return funcion()
        except excepciones as e:
            if numero == intentos:
                e.add_note(f"Fallaron los {intentos} intentos")
                raise

