import warnings


def aplicar_descuento(precio, porcentaje):
    """Aplica un descuento porcentual; avisa si supera el 50 %."""
    if precio < 0:
        raise ValueError(f"precio negativo: {precio}")
    if not 0 <= porcentaje <= 100:
        raise ValueError(f"porcentaje fuera de rango (0-100): {porcentaje}")
    if porcentaje > 50:
        warnings.warn(f"descuento inusualmente alto: {porcentaje} %", UserWarning, stacklevel=2)
    return round(precio * (1 - porcentaje / 100), 2)

