import logging

log = logging.getLogger("pagos")


def procesar_pagos(pagos):
    """Suma los importes válidos y registra cada incidencia con logging."""
    total = 0
    for numero, texto in enumerate(pagos, start=1):
        try:
            importe = float(texto)
        except ValueError:
            log.error("Pago %d no válido: %r", numero, texto)
            continue
        if importe <= 0:
            log.warning("Pago %d ignorado: %s", numero, importe)
            continue
        total += importe
        log.debug("Pago %d aceptado: %s", numero, importe)
    log.info("Total: %.2f", total)
    return round(total, 2)

