def preparar(fallo_abrir=None, fallo_usar=None, fallo_cerrar=None):
    """Devuelve (abrir, usar, cerrar, eventos). Cada fallo_* es una excepción que lanzar, o None."""
    eventos = []

    def abrir():
        eventos.append("abrir")
        if fallo_abrir is not None:
            raise fallo_abrir
        return "recurso"

    def usar(recurso):
        eventos.append("usar " + recurso)
        if fallo_usar is not None:
            raise fallo_usar
        return 42

    def cerrar(recurso):
        eventos.append("cerrar " + recurso)
        if fallo_cerrar is not None:
            raise fallo_cerrar

    return abrir, usar, cerrar, eventos

exercises.solution:
def usar_recurso(abrir, usar, cerrar):
    """Usa un recurso y lo cierra siempre, sin perder ningún error."""
    recurso = abrir()               # si falla, no hay nada que cerrar
    try:
        resultado = usar(recurso)
    except Exception as error_uso:
        try:
            cerrar(recurso)
        except Exception as error_cierre:
            raise ExceptionGroup(
                "fallo al usar y al cerrar el recurso", [error_uso, error_cierre]
            ) from None
        raise                       # solo falló usar: relanzamos su excepción
    except BaseException:           # KeyboardInterrupt, SystemExit...
        cerrar(recurso)
        raise
    else:
        cerrar(recurso)             # si esto falla, su excepción se propaga
    return resultado

