exercises.solution:
def validar_pedido(pedido):
    """Devuelve True si el pedido es válido; si no, lanza un ExceptionGroup con todos los errores."""
    errores = []

    if "cliente" not in pedido:
        errores.append(KeyError("cliente"))
    elif not isinstance(pedido["cliente"], str):
        errores.append(TypeError("cliente: se esperaba str"))
    elif not pedido["cliente"].strip():
        errores.append(ValueError("cliente: no puede estar vacío"))

    if "cantidad" not in pedido:
        errores.append(KeyError("cantidad"))
    elif isinstance(pedido["cantidad"], bool) or not isinstance(pedido["cantidad"], int):
        errores.append(TypeError("cantidad: se esperaba int"))
    elif pedido["cantidad"] <= 0:
        errores.append(ValueError("cantidad: debe ser mayor que 0"))

    if "precio" not in pedido:
        errores.append(KeyError("precio"))
    elif isinstance(pedido["precio"], bool) or not isinstance(pedido["precio"], (int, float)):
        errores.append(TypeError("precio: se esperaba número"))
    elif pedido["precio"] < 0:
        errores.append(ValueError("precio: no puede ser negativo"))

    if "email" not in pedido:
        errores.append(KeyError("email"))
    elif not isinstance(pedido["email"], str):
        errores.append(TypeError("email: se esperaba str"))
    elif "@" not in pedido["email"]:
        errores.append(ValueError("email: falta '@'"))

    if errores:
        raise ExceptionGroup("pedido inválido", errores)
    return True


def resumir_errores(pedido):
    """Clasifica los errores de validar_pedido por tipo usando except*."""
    resumen = {"faltan": [], "tipo": [], "valor": []}
    try:
        validar_pedido(pedido)
    except* KeyError as grupo:
        resumen["faltan"] = [e.args[0] for e in grupo.exceptions]
    except* TypeError as grupo:
        resumen["tipo"] = [str(e) for e in grupo.exceptions]
    except* ValueError as grupo:
        resumen["valor"] = [str(e) for e in grupo.exceptions]
    return resumen

