def transferir(cuentas, origen, destino, importe):
    """Aplica un movimiento o lanza la excepción correspondiente sin tocar nada."""
    if origen not in cuentas:
        raise KeyError(origen)
    if destino not in cuentas:
        raise KeyError(destino)
    if importe <= 0:
        raise ValueError(f"importe no válido: {importe}")
    if cuentas[origen] < importe:
        raise ValueError(f"saldo insuficiente en {origen!r}")
    cuentas[origen] -= importe
    cuentas[destino] += importe


def aplicar_movimientos(cuentas, movimientos):
    """Aplica todos los movimientos o ninguno."""
    copia = dict(cuentas)                   # instantánea para poder deshacer
    for numero, movimiento in enumerate(movimientos, start=1):
        try:
            transferir(cuentas, *movimiento)
        except Exception as e:
            cuentas.clear()
            cuentas.update(copia)           # deshacer en el MISMO diccionario
            e.add_note(f"movimiento {numero}: {movimiento!r}")
            raise
    return len(movimientos)

