exercises.solution:
class ErrorRPN(Exception):
    """Base de los errores del evaluador RPN."""


class TokenInvalidoError(ErrorRPN):
    """Un token no es ni número ni operador."""

    def __init__(self, token, posicion):
        super().__init__(f"token no válido {token!r} en la posición {posicion}")
        self.token = token
        self.posicion = posicion


class FaltanOperandosError(ErrorRPN):
    """Un operador no tiene dos operandos en la pila."""

    def __init__(self, operador, posicion):
        super().__init__(f"faltan operandos para {operador!r} en la posición {posicion}")
        self.operador = operador
        self.posicion = posicion


class DivisionPorCeroError(ErrorRPN):
    """División entre cero durante la evaluación."""

    def __init__(self, posicion):
        super().__init__(f"división por cero en la posición {posicion}")
        self.posicion = posicion


class ExpresionIncompletaError(ErrorRPN):
    """Al terminar no queda exactamente un valor en la pila."""

    def __init__(self, sobrantes):
        super().__init__(f"expresión incompleta: quedan {sobrantes} valores en la pila")
        self.sobrantes = sobrantes


OPERADORES = ("+", "-", "*", "/")


def a_numero(token, posicion):
    """Convierte un token en int o float, o lanza TokenInvalidoError."""
    try:
        return int(token)
    except ValueError:
        pass
    try:
        return float(token)
    except ValueError:
        raise TokenInvalidoError(token, posicion) from None


def operar(a, b, operador, posicion):
    """Aplica el operador; traduce la división entre cero."""
    if operador == "+":
        return a + b
    if operador == "-":
        return a - b
    if operador == "*":
        return a * b
    try:
        return a / b
    except ZeroDivisionError as e:
        raise DivisionPorCeroError(posicion) from e


def evaluar_rpn(expresion):
    """Evalúa una expresión en notación polaca inversa."""
    pila = []
    for posicion, token in enumerate(expresion.split(), start=1):
        if token in OPERADORES:
            if len(pila) < 2:
                raise FaltanOperandosError(token, posicion)
            b = pila.pop()
            a = pila.pop()
            pila.append(operar(a, b, token, posicion))
        else:
            pila.append(a_numero(token, posicion))
    if len(pila) != 1:
        raise ExpresionIncompletaError(len(pila))
    return pila[0]


def evaluar_lote(expresiones):
    """Evalúa varias expresiones; agrupa los errores RPN en un ExceptionGroup."""
    resultados = []
    errores = []
    for numero, expresion in enumerate(expresiones, start=1):
