exercises.solution:
import logging

log = logging.getLogger("importador")


class ErrorImportacion(Exception):
    """Base de los errores de importación; guarda el número de línea."""

    def __init__(self, numero, mensaje):
        super().__init__(f"línea {numero}: {mensaje}")
        self.numero = numero


class ErrorFormato(ErrorImportacion):
    """La línea no tiene los 3 campos esperados."""

    def __init__(self, numero, linea):
        super().__init__(numero, "se esperaban 3 campos separados por ';'")
        self.linea = linea


class ErrorDato(ErrorImportacion):
    """Un campo tiene un valor no válido."""

    def __init__(self, numero, campo, valor):
        super().__init__(numero, f"valor no válido en {campo}: {valor!r}")
        self.campo = campo
        self.valor = valor


class CodigoDuplicadoError(ErrorImportacion):
    """El código de producto ya se había importado."""

    def __init__(self, numero, codigo):
        super().__init__(numero, f"código repetido {codigo!r}")
        self.codigo = codigo


def leer_producto(numero, linea):
    """Convierte una línea 'codigo;cantidad;precio' en una tupla validada."""
    partes = linea.split(";")
    if len(partes) != 3:
        raise ErrorFormato(numero, linea)
    codigo, texto_cantidad, texto_precio = [parte.strip() for parte in partes]
    if not codigo:
        raise ErrorDato(numero, "codigo", codigo)
    try:
        cantidad = int(texto_cantidad)
    except ValueError as e:
        raise ErrorDato(numero, "cantidad", texto_cantidad) from e
    if cantidad < 0:
        raise ErrorDato(numero, "cantidad", texto_cantidad)
    try:
        precio = float(texto_precio)
    except ValueError as e:
        raise ErrorDato(numero, "precio", texto_precio) from e
    if precio <= 0:
        raise ErrorDato(numero, "precio", texto_precio)
    return codigo, cantidad, precio


def importar(texto, estricto=False):
    """Importa el inventario; tolerante por defecto, estricto si se pide."""
    productos = {}
    errores = []
    for numero, linea in enumerate(texto.splitlines(), start=1):
        contenido = linea.strip()
        if not contenido or contenido.startswith("#"):
            continue
        try:
            codigo, cantidad, precio = leer_producto(numero, linea)
            if codigo in productos:
                raise CodigoDuplicadoError(numero, codigo)
        except ErrorImportacion as e:
            log.warning("%s", e)
            errores.append(e)
        else:
            productos[codigo] = {"cantidad": cantidad, "precio": precio}
    log.info("Importados %d productos, %d errores", len(productos), len(errores))
    if estricto and errores:
        raise ExceptionGroup("importación fallida", errores)
    return productos, errores


def resumen_errores(texto):
    """Resume por tipo los errores de una importación estricta."""
    resumen = {"formato": [], "datos": [], "duplicados": []}
    try:
        importar(texto, estricto=True)
    except* ErrorFormato as grupo:
        resumen["formato"] = [e.numero for e in grupo.exceptions]
    except* ErrorDato as grupo:
        resumen["datos"] = [(e.numero, e.campo) for e in grupo.exceptions]
    except* CodigoDuplicadoError as grupo:
        resumen["duplicados"] = [e.codigo for e in grupo.exceptions]
    return resumen

