        leer_producto(4, linea)
    except ErrorFormato as e:
        assert (e.numero, e.linea) == (4, linea), f"ErrorFormato debe guardar el número (4) y la línea original ({linea!r})"
    else:
        raise AssertionError(f"{linea!r} no tiene 3 campos: debe lanzar ErrorFormato")

casos = [
    (" ;1;1", "codigo", ""),
    ("A1;x;1", "cantidad", "x"),
    ("A1;-1;1", "cantidad", "-1"),
    ("A1;2.5;1", "cantidad", "2.5"),
    ("A1;1;0", "precio", "0"),
    ("A1;1;gratis", "precio", "gratis"),
]
for linea, campo, valor in casos:
    try:
        leer_producto(9, linea)
    except ErrorDato as e:
        assert (e.numero, e.campo, e.valor) == (9, campo, valor), f"Para {linea!r} se esperaba ErrorDato(9, {campo!r}, {valor!r}), no ({e.numero}, {e.campo!r}, {e.valor!r})"
    else:
        raise AssertionError(f"{linea!r} debe lanzar ErrorDato en el campo {campo!r}")

